//! Every model, in catalog order. Generated from the 2.10 ZDL descriptors.
use crate::{Effect, catalog::ModelInfo};

macro_rules! models {
    ($($variant:ident => $group:ident::$module:ident),* $(,)?) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
        pub enum Model {
            $($variant),*
        }
        impl Model {
            pub const ALL: &'static [Model] = &[$(Model::$variant),*];
            pub fn info(self) -> &'static ModelInfo {
                match self {
                    $(Model::$variant => &crate::fx::$group::$module::INFO),*
                }
            }
            /// Allocates every buffer the model needs; call off the audio thread.
            pub fn create(self, sample_rate: f32) -> Box<dyn Effect> {
                match self {
                    $(Model::$variant => crate::fx::$group::$module::create(sample_rate)),*
                }
            }
        }
    };
}

